201	  test('registered: shows the registered body copy and only the Continue Shopping CTA', () => {
202	    mockEinsteinReturn(false, []);
203	
204	    renderPage(true);
205	
206	    expect(screen.getByTestId('recently-viewed-empty')).toBeInTheDocument();
207	    expect(screen.queryByTestId('zimm-recently-viewed-grid-stub')).not.toBeInTheDocument();
