210	    expect(screen.getByRole('link', { name: 'Continue Shopping' })).toBeInTheDocument();
211	    expect(screen.queryByRole('link', { name: 'Sign In' })).not.toBeInTheDocument();
212	    expect(mockSelectRecentlyViewedFullHistoryCard).not.toHaveBeenCalled();
213	  });
214	
215	  test('guest: shows the guest body copy and both Continue Shopping and Sign In CTAs', () => {
216	    mockEinsteinReturn(false, []);
217	
218	    renderPage(false);
