271	      primaryImage: { src: 'https://example.test/image.jpg', alt: product?.name ?? '' },
272	      variation: 'plp',
273	    }));
274	
275	    renderPage(true);
276	
277	    const gridProps = mockZimmRecentlyViewedGrid.mock.calls[0][0];
278	    expect(gridProps.itemCountLabel).toBe('2 items');
279	  });
280	});
281	
282	describe('RecentlyViewed — size-aware Add to Bag (2026-09-09, full parity with product-list/index.tsx)', () => {
283	  const buildCard = (id: string, name: string) => ({
284	    id,
285	    href: `/product/${id}`,
286	    name,
287	    headingLevel: 'h3' as const,
288	    primaryImage: { src: 'https://example.test/image.jpg', alt: name },
289	    variation: 'plp' as const,
290	  });
291	
292	  test("with no size selected, adds the product's own default id/price and never calls resolveOrderableVariant", () => {
293	    const addItemToNewOrExistingBasket = vi.fn().mockResolvedValue(undefined);
294	    mockEinsteinReturn(false, [{ ...mockProducts[0], price: 250 }]);
295	    mockSelectRecentlyViewedFullHistoryCard.mockReturnValue(buildCard('rv-1', 'Product One'));
296	
297	    renderPage(true, addItemToNewOrExistingBasket);
298	
299	    const gridProps = mockZimmRecentlyViewedGrid.mock.calls[0][0];
300	    act(() => {
301	      asPlpCard(gridProps.cards[0]).onAddToBag?.();
302	    });
303	
304	    expect(mockResolveOrderableVariant).not.toHaveBeenCalled();
305	    expect(addItemToNewOrExistingBasket).toHaveBeenCalledWith([{ productId: 'rv-1', price: 250, quantity: 1 }]);
306	  });
307	
308	  test('selecting a size chip then adding to bag resolves the real orderable variant for that card only', () => {
309	    const addItemToNewOrExistingBasket = vi.fn().mockResolvedValue(undefined);
310	    mockEinsteinReturn(false, mockProducts);
311	    mockSelectRecentlyViewedFullHistoryCard.mockImplementation((product) =>
312	      buildCard(product?.id ?? '', product?.name ?? ''),
313	    );
314	    mockResolveOrderableVariant.mockImplementation((product, sizeValue) =>
315	      product.id === 'rv-1' && sizeValue === 'xs' ? { productId: 'rv-1-XS', price: 300, orderable: true } : null,
316	    );
317	
318	    renderPage(true, addItemToNewOrExistingBasket);
319	
320	    // Selecting a size chip is a state update outside a real DOM event -- act() flushes it so the
321	    // next render's props (captured below, not the stale first-render snapshot) reflect it.
322	    act(() => {
323	      asPlpCard(mockZimmRecentlyViewedGrid.mock.calls[0][0].cards[0]).onSizeChipSelect?.('xs');
324	    });
325	
326	    const latestCall = mockZimmRecentlyViewedGrid.mock.calls[mockZimmRecentlyViewedGrid.mock.calls.length - 1][0];
327	    // Only rv-1's card picked up the selection -- rv-2's own selectedSizeChipValue is untouched,
328	    // proving this is a per-card id-keyed map, not one shared piece of page-level state.
329	    expect(asPlpCard(latestCall.cards[0]).selectedSizeChipValue).toBe('xs');
330	    expect(asPlpCard(latestCall.cards[1]).selectedSizeChipValue).toBeUndefined();
331	
332	    act(() => {
333	      asPlpCard(latestCall.cards[0]).onAddToBag?.();
334	    });
335	
336	    expect(mockResolveOrderableVariant).toHaveBeenCalledWith(mockProducts[0], 'xs');
337	    expect(addItemToNewOrExistingBasket).toHaveBeenCalledWith([{ productId: 'rv-1-XS', price: 300, quantity: 1 }]);
338	  });
339	
340	  test("a selection matching no real variant falls back to the product's own default id/price, same as no selection at all", () => {
341	    const addItemToNewOrExistingBasket = vi.fn().mockResolvedValue(undefined);
342	    mockEinsteinReturn(false, [{ ...mockProducts[0], price: 250 }]);
343	    mockSelectRecentlyViewedFullHistoryCard.mockReturnValue(buildCard('rv-1', 'Product One'));
344	    mockResolveOrderableVariant.mockReturnValue(null);
345	
346	    renderPage(true, addItemToNewOrExistingBasket);
347	
348	    act(() => {
349	      asPlpCard(mockZimmRecentlyViewedGrid.mock.calls[0][0].cards[0]).onSizeChipSelect?.('no-such-size');
350	    });
351	    const latestCall = mockZimmRecentlyViewedGrid.mock.calls[mockZimmRecentlyViewedGrid.mock.calls.length - 1][0];
352	    act(() => {
353	      asPlpCard(latestCall.cards[0]).onAddToBag?.();
354	    });
355	
356	    expect(addItemToNewOrExistingBasket).toHaveBeenCalledWith([{ productId: 'rv-1', price: 250, quantity: 1 }]);
357	  });
358	});
