  }, [zone, recommender, _products]);

  useEffect(() => {
    // This is an optimization that eliminates superfluous rerenders/fetching by
    // keeping a copy of the `products` array prop in state for shallow comparison.
    if (!Array.isArray(products)) {
      return;
    }
    if (products.length !== _products?.length || !products.every((val, index) => val === _products?.[index])) {
      setProducts(products);
    }
  }, [products]);

  useEffect(() => {
    if (isOnScreen && recommendations?.recs) {
      sendViewReco(
        {
          recommenderName: recommendations.recommenderName,
          __recoUUID: recommendations.recoUUID,
        },
        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
      );
      dataCloud.sendViewRecommendations(
        {
          recommenderName: recommendations.recommenderName,
          __recoUUID: recommendations.recoUUID,
        },
        recommendations.recs.map((rec: { id?: string }) => ({ id: rec.id })),
      );
    }
  }, [isOnScreen, recommendations]);

  // SFCC-83 — Recently Viewed only. Every other recommender falls through to the unchanged
  // ProductScroller branch below. This branch sits ahead of the base dead-check below (see this
  // file's own module docblock, point 3, for why that no longer strictly matters but is kept
  // anyway) — every path inside this `if` returns on its own, so it never falls through to that
  // dead-check or the ProductScroller return regardless. Every other recommender is unaffected:
  // they still hit the exact same dead-check + ProductScroller path below, unchanged, just after
  // this check now short-circuits past them when it applies.
  if (recommender === EINSTEIN_RECOMMENDERS.PDP_RECENTLY_VIEWED) {
    // Cart exclusion (2026-09-10, Marcel) — see the isCartPage constant's own comment above for
    // why this can't be expressed as a distinct recommender value. No rail, no title, no
    // placeholder — same treatment as the empty-state gate below, just for a different reason.
    if (isCartPage) {
      return null;
    }

    // AC 8's empty-state gate, now against Einstein's own recs directly (build plan step E1) —
    // see this file's own module docblock for why this one check covers both the loading case
    // (`recs` undefined until `getRecommendations` resolves) and the true zero-history case. No
    // rail, no title, no placeholder.
    if (!recommendations?.recs?.length) {
      return null;
    }

    // `recommendations.recs` is `useEinstein()`'s own untyped (`any`) result — like the
    // `.find`/`.some`/`.map` callbacks elsewhere in this file that already read off it, the
    // mapping callback below needs an explicit parameter-type annotation to satisfy
    // `noImplicitAny`. `RecentlyViewedProduct` (recentlyViewedCard.ts's own alias for
    // `ShopperProductsTypes.Product`) is reused here rather than a hand-rolled inline shape, since
    // it already names every field `selectRecentlyViewedCard` reads, and this input is a strict
    // superset of it (see the module docblock above).
    const cards: ZimmProductCardProps[] = recommendations.recs
      .map((product: RecentlyViewedProduct) => selectRecentlyViewedCard(product, formatPrice))
      .filter((card: RecentlyViewedCard | null): card is RecentlyViewedCard => card !== null)
      .map(
        (card: RecentlyViewedCard): ZimmProductCardProps => ({
          ...card,
          // Inert for this variation — ZimmProductCardContent never mounts when
          // variation: 'recentlyViewed' (zimmProductCard/index.tsx's
          // VARIATION_CONFIG.showContent). 'h3' matches the one other established value for
          // this same required field (product-list/productListCardMapper.ts).
          headingLevel: 'h3',
          variation: 'recentlyViewed',
        }),
      );

    // The See-Full-History link, finally wired in (was a stated "not yet built" gap on every
    // caller until now). Triggers when the shopper has more recently-viewed products
    // than fit in view at the *current* breakpoint — matching the AC's own "exceeds the visible
    // rail width" wording, which is viewport-relative, not a flat count. Compared against
    // `cards.length` (the full, unsliced count this container just built — up to
    // RECENTLY_VIEWED_HISTORY_MAX_STORED, 24), not the rail's own internal 5-item render slice,
    // since the question is "does more exist than is visible", not "did we cap the render".
    const showSeeAllLink = cards.length > visibleCardCount;

    return (
      // Ref-attachment point — see the module docblock's own isOnScreen/forwardRef note above for
      // why this wrapper exists at all. `{...props}` forwards the caller's own layout props (e.g.
      // PDP's `mx={{base: -4, md: -8, lg: 0}}`, Cart's `mx={{base: -4, sm: -6, lg: 0}}`) exactly
      // as the ProductScroller branch below already does — without it, this branch would render
      // inset inside the page's normal content padding while every sibling rail on the same page
      // bleeds edge-to-edge, and zimmRecentlyViewedRail.css.ts's own card-width math (e.g.
      // 201x2=402) assumes the full viewport width is actually available. `title` is passed
      // straight through with no `recommendations?.displayMessage` fallback — this component owns
      // no copy of its own for this branch (build plan A5/A6): the real title always comes from
      // the caller, regardless of whether Einstein's own `displayMessage` is present.
      <Box ref={ref} {...(props as BoxProps)}>
        <ZimmRecentlyViewedRail
          title={title}
          cards={cards}
          seeAllHref={showSeeAllLink ? buildUrl(RECENTLY_VIEWED_ROUTE) : undefined}
          seeAllLabel={showSeeAllLink ? intl.formatMessage(messages.seeFullHistory) : undefined}
        />
      </Box>
    );
  }

  // The component should remove itself altogether if it has no recommendations
  // and we aren't loading any.
  if (!isLoading && (!recommendations || recommendations.length < 1)) {
    return null;
  }

  // TODO: DRY this handler when intl provider is available globally
  const addItemToWishlist = async (product: RecommendedProduct) => {
    try {
      if (!wishlist || !customerId) {
        return;
      }
      await createCustomerProductListItem.mutateAsync({
        parameters: {
          listId: wishlist.id,
          customerId,
        },
        body: {
          quantity: 1,
          productId: product.productId,
          public: false,
          priority: 1,
          type: 'product',
        },
      });

      toast({
        title: intl.formatMessage(TOAST_MESSAGE_ADDED_TO_WISHLIST, { quantity: 1 }),
        status: 'success',
        action: (
          // it would be better if we could use <Button as={Link}>
          // but unfortunately the Link component is not compatible
          // with Chakra Toast, since the ToastManager is rendered via portal
          // and the toast doesn't have access to intl provider, which is a
          // requirement of the Link component.
          <Button variant="link" onClick={() => navigate('/account/wishlist')}>
            {intl.formatMessage(TOAST_ACTION_VIEW_WISHLIST)}
          </Button>
        ),
      });
    } catch {
      toast({
        title: intl.formatMessage(API_ERROR_MESSAGE),
        status: 'error',
      });
    }
  };

  const removeItemFromWishlist = async (product: RecommendedProduct) => {
    try {
      const wishlistItem = wishlist?.customerProductListItems?.find(
        (item: { productId?: string }) => item.productId === product.productId,
      );
      if (!wishlistItem || !wishlist || !customerId) {
        return;
      }
      await deleteCustomerProductListItem.mutateAsync({
        parameters: {
          customerId,
          itemId: wishlistItem.id,
          listId: wishlist.id,
        },
      });
      toast({
        title: intl.formatMessage(TOAST_MESSAGE_REMOVED_FROM_WISHLIST),
        status: 'success',
        id: product.productId,
      });
    } catch {
      toast({
        title: intl.formatMessage(API_ERROR_MESSAGE),
        status: 'error',
      });
    }
  };

  return (
    <ProductScroller
      ref={ref}
      title={title || recommendations?.displayMessage}
      products={recommendations.recs}
      isLoading={isLoading}
      productTileProps={(product: RecommendedProduct) => ({
        onClick: () => {
          sendClickReco(
            {
              recommenderName: recommendations.recommenderName,
              __recoUUID: recommendations.recoUUID,
            },
            product,
          );
        },
        enableFavourite: true,
        isFavourite: wishlist?.customerProductListItems?.some(
          (item: { productId?: string }) => item.productId === product?.productId,
        ),
        onFavouriteToggle: (toBeFavourite: boolean) => {
          const action = toBeFavourite ? addItemToWishlist : removeItemFromWishlist;
          return action(product);
        },
      })}
      {...props}
    />
  );
};

export default RecommendedProducts;

/**
 * Maps one Recently Viewed product to the FULL `ZimmProductCard` props Recently Viewed's Full
 * History page (SFCC-84) renders — badge, size chips, was/now pricing and a multi-image gallery,
 * i.e. the `plp` variation's already-shipped shape, not `recentlyViewedCard.ts`'s narrower
 * image-only rail shape (SFCC-83's `recentlyViewed` variation). Both mappers read the same
 * underlying input — a plain Commerce API `Product` from `recentlyViewedProductFetch.ts`'s own
 * `getProducts` call — but produce deliberately different output shapes for two deliberately
 * different surfaces; see that mapper's own docblock for the rail's narrower contract and why it
 * stops at image-only.
 *
 * Added per the build plan's B2 discussion (finding 41b): "reuse the rail's mapper" was the
 * original, incorrect assumption for this page — `recentlyViewedCard.ts` cannot produce this
 * shape by its own design (image-only, no price, no gallery), so a second, separate mapper is
 * required. Per Jasmijn's SFCC-84 comment, the Full History card's default state is "image, name,
 * badge, price (incl. was/now), and cart icon" — exactly the `plp` variation's shape, which is why
 * this mapper's output includes `headingLevel: 'h3'` and `variation: 'plp'` directly (unlike
 * `recentlyViewedCard.ts`'s `RecentlyViewedCard`, which deliberately excludes both as its rail
 * container's job) — mirroring `productListCardMapper.ts`'s own `ProductListCardResult`, which
 * bakes in the same two fields for the same reason: its output is meant to be spread straight
 * into `<ZimmProductCard>` with nothing left for a caller to add.
 *
 * Modelled on `recentlyViewedCard.ts`'s general style/docblock conventions (no React/react-intl
 * import, `formatPrice` injected as a parameter, same hard `null`-gate contract for a product
 * with no usable name/image) and on `overrides/app/pages/product-list/productListCardMapper.ts`
 * (the closest existing precedent producing this exact `plp`-variation output shape from a real
 * product). Ported, not imported, from both — a genuinely separate, self-contained module with
 * its own local type aliases, the same relationship `recentlyViewedCard.ts` already has to
 * `productListCardMapper.ts` (see that file's own docblock).
 *
 * **What's ported near-verbatim from `productListCardMapper.ts`, and what changed:**
 * `selectSizeChipValues` is re-pointed at `product.variationAttributes` directly (the plain
 * `Product` shape) in place of a `ProductSearchHit`'s own same-named field — the underlying
 * `VariationAttribute` shape is the same `commerce-sdk-isomorphic` type either way, so the
 * picking/mapping logic itself needed no change, only the input type.
 *
 * **Image resolution — revised 2026-09-09 to close the same real bug already fixed on
 * `productListCardMapper.ts` and `recentlyViewedCard.ts`: a colour-blind image pick, and API array
 * order trusted over the image filename's own sequence number.** `selectGalleryImages` used to
 * pick "whichever image group has the most images," viewtype-agnostic — actually a worse version
 * of the same bug: no colour scoping meant a multi-colour product's gallery could mix different
 * colours' photos, and no viewtype restriction meant it could pick a non-`medium` group (an
 * oversized image at thumbnail size, against AGENTS.md's image-sizing rule). Now shares one
 * `selectColourScopedImages` resolution — colour-scoped `filterImageGroups` first (colour from
 * `resolveViewedColour`, which is only ever the fallback half of `productListCardMapper.ts`'s own
 * `resolveRepresentativeColour`: this input has no `representedProduct` field, see that function's
 * own doc), falling back to a viewtype-only match for a genuinely single-colour product whose one
 * group carries no colour tag at all, then sorted by the image filename's own sequence number
 * (same real defect: a colour-tagged group can come back `[2, 1, ...]`, not ascending). This one
 * array now feeds `primaryImage`, `primaryImageFallbacks`, `hoverImage` and `images` — mirroring
 * `productListCardMapper.ts`'s own `selectProductListCard` exactly, except `primaryImage` is the
 * array's own first entry rather than a separately-sourced `hit.image` (a plain `getProducts`
 * `Product` has no equivalent flat `image` field — a Search-hit-only convenience field) — the same
 * adaptation `recentlyViewedCard.ts` already made for its own single-image case.
 *
 * **Price handling is deliberately NOT copied from `productListCardMapper.ts`.** That mapper reads
 * the flat `hit.price` field for `currentPrice` while leaving `originalPrice` unset entirely — had
 * it called `getPriceData(hit).listPrice` for `originalPrice` while keeping `hit.price` for
 * `currentPrice`, the two would risk disagreeing on a multi-variant product, since `getPriceData`
 * internally sources its own `currentPrice` from `findLowestPrice()`, not from a flat `price`
 * field. Both `currentPrice` and `originalPrice` here come from one `getPriceData(product)` call
 * (base SFCC, `node_modules/@salesforce/retail-react-app/app/utils/product-utils.js:123-170`,
 * confirmed by reading it directly) so the two halves can never disagree. `originalPrice` is only
 * ever set when that same call's `isOnSale` is `true` — a not-on-sale product must not render a
 * crossed-out price identical to its current one.
 *
 * **Badge — confirmed live, 2026-09-09, closing what was a real, stated gap.** Previously left
 * `undefined`: `ShopperProductsTypes.Product` has no typed `c_productBadges` field, and it was
 * unconfirmed whether the `getProducts` hydration endpoint populates this custom attribute at all
 * (as opposed to the search-index endpoint `productListCardMapper.ts` reads it from). Checked
 * directly against a real badged product (`4673TS251`) via a live PDP fetch (which reads the same
 * `ShopperProductsTypes.Product` shape `getProducts` does — `product-detail/index.tsx`'s own
 * `useProduct` call): the field is genuinely present — `c_productBadges: [{productBadge: 'Runway',
 * productBadgeUrl: '/category/runway'}, {productBadge: 'Exclusive', productBadgeUrl:
 * '/category/exclusive'}]` — confirming the hydration endpoint does carry it, at least for this
 * product. Interestingly, the *same* product's Search hit carried no `c_productBadges` at all at
 * the same moment — most likely the search index simply hadn't caught up yet with a recently-added
 * badge (SFCC search indexes rebuild on their own schedule, separate from live product/master data
 * reads), not a real difference in what each endpoint is capable of returning — but that's a
 * hypothesis, not independently re-verified here.
 *
 * `productBadgeUrl` is a real field on the live data above, discovered by this check — not
 * consumed here or anywhere in this codebase today. `badge` stays a plain label string (matching
 * `ZimmProductCardBaseProps.badge?: string`, and `productListCardMapper.ts`'s own read of the same
 * shape) — turning a badge into a link is a real, undesigned UI decision, not something to invent
 * silently here.
 */
import type { ShopperProductsTypes } from 'commerce-sdk-isomorphic';
import { getPriceData, filterImageGroups } from '@salesforce/retail-react-app/app/utils/product-utils';
import { productUrlBuilder } from '@salesforce/retail-react-app/app/utils/url';
import type {
  ZimmProductCardBaseProps,
  ZimmProductCardPlpVariation,
  ZimmProductCardImage,
} from '../components/ui-kits/organisms/zimmProductCard';
import type { ZimmSizeChipValue } from '../components/ui-kits/molecules/zimmSizeChipGroup';
import {
  sortImagesBySequence,
  resolveFallbackColour,
  toGalleryAlt,
  resolveRequiredAlt,
} from './productCardMappingHelpers';

/**
 * The real Commerce API `Product` this mapper reads — the same `ShopperProductsTypes.Product`
 * `recentlyViewedProductFetch.ts` produces and `recentlyViewedCard.ts` also consumes, augmented
 * with `c_productBadges` — same narrow-augmentation pattern as `productListCardMapper.ts`'s own
 * `ProductListSearchHit`, and the same reasoning: the SDK's own `Product` type has no field for
 * this custom attribute, only a generic `{[key: string]: any}` index signature, so this documents
 * the real, confirmed-live shape (see this module's own docblock's "Badge" section) rather than
 * reading through `any`. Not otherwise an augmentation — everything else this mapper reads is
 * already typed by the SDK — so this stays close to "a plain alias" in spirit, just no longer
 * literally one.
 */
export type RecentlyViewedFullHistoryProduct = ShopperProductsTypes.Product & {
  // productBadgeUrl is real, confirmed-live data (see this module's own docblock's "Badge"
  // section) but genuinely unused below -- typed anyway so a test fixture built from the real
  // wire shape doesn't have to omit it to satisfy this type.
  c_productBadges?: Array<{ productBadge?: string; productBadgeUrl?: string }>;
};

/** Formats a bare amount for the storefront. Injected so this module stays free of react-intl —
 *  same shape as `recentlyViewedCard.ts`'s own `FormatPrice`, redeclared locally for the same
 *  separate-module reason as `RecentlyViewedFullHistoryProduct` above. */
export type FormatPrice = (amount: number, currency: string) => string;

/**
 * The full `plp`-variation `ZimmProductCard` props this mapper produces — badge, size chips,
 * was/now pricing, multi-image gallery, heading level and variation all included. Mirrors
 * `productListCardMapper.ts`'s own `ProductListCardResult` (unexported from that file, so
 * redeclared here rather than imported) — this mapper's output is meant to be spread straight
 * into `<ZimmProductCard>` by its page container (SFCC-84's Full History page, not yet built)
 * with nothing left to add, the same convenience that shape already gives PLP's own page.
 */
export type RecentlyViewedFullHistoryCard = ZimmProductCardBaseProps & ZimmProductCardPlpVariation;

/** The correctly-sized product image view for the required `primaryImage` slot — same constant,
 *  same reasoning, as `recentlyViewedCard.ts`'s own `MEDIUM_VIEW_TYPE`: never serve an
 *  arbitrary-sized image at thumbnail size (AGENTS.md's image-sizing guidance). */
const MEDIUM_VIEW_TYPE = 'medium';

/** The variation-attribute id this mapper reads for size chips — named per conventions.md's
 *  no-magic-strings rule. `productListCardMapper.ts`'s own `selectSizeChipValues`, which this is
 *  ported from, uses the literal inline; named here instead since this is a fresh file. */
const SIZE_VARIATION_ATTRIBUTE_ID = 'size';

/** The variation-attribute id `filterImageGroups` matches an image group's colour against — same
 *  constant, same reasoning, as `productListCardMapper.ts`'s own. */
const COLOUR_VARIATION_ATTRIBUTE_ID = 'color';

/**
 * Resolves which real colour this product's images should come from — now the shared
 * `resolveFallbackColour` (`productCardMappingHelpers.ts`) directly, same as
 * `recentlyViewedCard.ts`'s identical `resolveViewedColour`: there is no `representedProduct`
 * branch to add here, since this input is a plain `ShopperProductsTypes.Product` (from
 * `getProducts`), which has no such field at all (confirmed against the SDK's own type).
 * `productListCardMapper.ts`'s own `resolveRepresentativeColour` layers exactly one extra branch
 * (a `representedProduct` match, Search-hit-only) in front of this same shared fallback. Returns
 * `undefined` when there are no variants at all — `selectColourScopedImages` below then falls back
 * to an unscoped, viewtype-only lookup, never a throw.
 */
const resolveViewedColour = (product: RecentlyViewedFullHistoryProduct): string | undefined =>
  resolveFallbackColour(product.variants, COLOUR_VARIATION_ATTRIBUTE_ID);

/**
 * Sorts by the merchandiser-assigned sequence number baked into each image's own filename
 * (e.g. `.../images/1.4673ts251.gvscp.guava-seascape.jpg` → `1`) — confirmed live on `4673TS251`,
 * whose colour-tagged medium group came back `[2, 1, 3, ...]`.
 *
 * Shared with `productListCardMapper.ts` and `recentlyViewedCard.ts` — see
 * `productCardMappingHelpers.ts`'s own docblock for why a shared primitive rather than three
 * separate copies (all three had drifted onto the identical non-transitive-comparator bug,
 * CodeRabbit 2026-09-10).
 */
const sortByImageSequence = (images: ZimmProductCardImage[]): ZimmProductCardImage[] =>
  sortImagesBySequence(images, (image) => image.src);

/**
 * `getPriceData`'s own return shape (base SFCC, `product-utils.js:123-170`, confirmed by reading
 * it directly), narrowed to the three fields this mapper reads. `@salesforce/retail-react-app`
 * ships no TypeScript types — this subpath falls through `overrides/app/types/vendor.d.ts`'s
 * catch-all `declare module '@salesforce/retail-react-app/*'`, a shorthand ambient module
 * declaration that types the whole module `any`, so `getPriceData`'s real return is implicitly
 * `any`. Declaring a local, narrow type for the fields actually read — rather than letting that
 * `any` propagate into this module's own types — matches `variantScopedPrice.ts`'s own
 * narrow-local-type pattern for the same untyped function (typescript.md's no-`any` rule). This
 * is a type annotation documenting an assumed shape, not a runtime guarantee: TypeScript allows
 * assigning `any` to any narrower type with no check, so the real correctness proof is the test
 * file's own direct comparison against a real `getPriceData` call, not this annotation alone.
 */
type SfccPriceData = {
  /** `findLowestPrice()`'s own `minPrice` — never `product.price` directly. This is the field
   *  `productListCardMapper.ts` does not use for its own `currentPrice` (it reads the flat
   *  `hit.price` field instead) — see this module's own docblock for why that risks disagreeing
   *  with a `getPriceData`-derived `originalPrice` on a multi-variant product. */
  currentPrice: number;
  /** The highest tiered price found — "was" price. `undefined` when the product has no
   *  `tieredPrices` at all (there is then no maximum to compute). */
  listPrice: number | undefined;
  /** `currentPrice < listPrice` — always `false`, never `true`, when `listPrice` is `undefined`
   *  (a numeric comparison against `undefined` evaluates to `false` in JS, never throws). */
  isOnSale: boolean;
};

/** The real `imageGroups[].images[]` element shape (`commerce-sdk-isomorphic`'s own
 *  `ShopperProductsTypes.Image`) — named `RawImage` to match `productListCardMapper.ts`'s own
 *  local name for the equivalent concept, but pointed at the real SDK type rather than that
 *  file's hand-rolled shape (AGENTS.md > Type Definitions: don't re-declare a type the SDK
 *  already exports). */
type RawImage = ShopperProductsTypes.Image;

const toCardImage = (image: RawImage | undefined): ZimmProductCardImage | undefined => {
  const src = image?.disBaseLink ?? image?.link;
  if (!src) return undefined;
  return { src, alt: toGalleryAlt(image?.alt) };
};

/**
 * The colour + `medium`-viewtype-scoped image list this product's card uses — one lookup feeding
 * four separate things below (`primaryImage`, the gallery, the hover-swap image, and the
 * broken-image fallback candidates), so none of them can ever disagree with each other or with the
 * resolved colour. Ported near-verbatim from `productListCardMapper.ts`'s own
 * `selectColourScopedImages`, re-pointed at `product.imageGroups` (the plain `getProducts` shape)
 * in place of a `ProductSearchHit`'s own same-named field — the underlying `ImageGroup`/`Image`
 * types are identical either way (confirmed directly against
 * `node_modules/commerce-sdk-isomorphic/lib/index.esm.d.ts`).
 *
 * **Two-pass, not one** — same real bug as `productListCardMapper.ts`'s own version closes: a
 * strict colour-scoped `filterImageGroups` match requires the group to explicitly declare a
 * matching `variationAttributes` entry, but a single-colour product's medium group commonly
 * carries no `variationAttributes` at all (nothing to disambiguate), which would make a
 * colour-scoped-only lookup exclude the group and return nothing. Falls back to a viewtype-only
 * match in that case. Never the reverse — a real colour-scoped match never falls back further, to
 * avoid re-mixing colours.
 */
const selectColourScopedImages = (
  product: RecentlyViewedFullHistoryProduct,
  colour: string | undefined,
): ZimmProductCardImage[] => {
  const colourScopedGroups = colour
    ? (filterImageGroups(product.imageGroups ?? [], {
        viewType: MEDIUM_VIEW_TYPE,
        variationValues: { [COLOUR_VARIATION_ATTRIBUTE_ID]: colour },
      }) as ShopperProductsTypes.ImageGroup[])
    : [];

  const groups =
    colourScopedGroups.length > 0
      ? colourScopedGroups
      : (filterImageGroups(product.imageGroups ?? [], {
          viewType: MEDIUM_VIEW_TYPE,
        }) as ShopperProductsTypes.ImageGroup[]);

  const images = (groups[0]?.images ?? [])
    .map(toCardImage)
    .filter((image): image is ZimmProductCardImage => Boolean(image));

  return sortByImageSequence(images);
};

/**
 * Picks this product's gallery from the colour-scoped image list above — matches
 * `ZimmProductCardMedia`'s own "no gallery" contract for 0 or 1 images (returns `undefined`, never
 * a 1-length array). Kept exported and independently tested, same as
 * `productListCardMapper.ts`'s own `selectGalleryImages` — `selectRecentlyViewedFullHistoryCard`
 * below calls `selectColourScopedImages` directly instead (one shared computation feeding
 * `primaryImage`/`primaryImageFallbacks`/`hoverImage`/`images` at once), matching that file's own
 * documented, deliberate minor redundancy rather than introducing a new one.
 */
export const selectGalleryImages = (product: RecentlyViewedFullHistoryProduct): ZimmProductCardImage[] | undefined => {
  const images = selectColourScopedImages(product, resolveViewedColour(product));
  return images.length > 1 ? images : undefined;
};

/**
 * Reads the "size" variation attribute (if this product has one) into the shape
 * `ZimmSizeChipGroup` expects. Ported near-verbatim from `productListCardMapper.ts`'s own
 * `selectSizeChipValues`, re-pointed at `product.variationAttributes` directly — `orderable` on
 * each value already reflects real stock for that specific size, so it maps directly to
 * `isDisabled` with no extra lookup needed.
 */
export const selectSizeChipValues = (product: RecentlyViewedFullHistoryProduct): ZimmSizeChipValue[] => {
  const sizeAttribute = product.variationAttributes?.find((attr) => attr.id === SIZE_VARIATION_ATTRIBUTE_ID);
  return (sizeAttribute?.values ?? []).map((value) => ({
    value: value.value,
    label: value.name ?? value.value,
    isDisabled: value.orderable === false,
  }));
};

/** What `resolveOrderableVariant` resolves a selected size chip value to — same shape, same
 *  reasoning, as `productListCardMapper.ts`'s own `ResolvedVariant`: the real, orderable SKU for
 *  that specific size, not the master id this product otherwise defaults to. */
export type ResolvedVariant = {
  productId: string;
  price: number | undefined;
  orderable: boolean;
};

/**
 * Resolves a selected size CHIP VALUE to its real orderable variant — ported near-verbatim from
 * `productListCardMapper.ts`'s own `resolveOrderableVariant`, re-pointed at this input's own
 * `variants` field (identical shape either way — both are `commerce-sdk-isomorphic` `Variant`
 * types). Returns `null` when there is no matching variant at all — callers fall back to this
 * product's own default id/price in that case, the same default that already existed before
 * size-aware Add to Bag was ever selectable.
 */
export const resolveOrderableVariant = (
  product: RecentlyViewedFullHistoryProduct,
  sizeValue: string,
): ResolvedVariant | null => {
  const variant = product.variants?.find((candidate) => candidate.variationValues?.size === sizeValue);
  if (!variant) return null;

  return {
    productId: variant.productId,
    price: variant.price,
    orderable: variant.orderable !== false,
  };
};

/**
 * Derives `currentPrice`/`originalPrice` from a single `getPriceData(product)` call — see this
 * module's own docblock for why both must come from the same call rather than mixing a flat
 * `product.price` field for one and `getPriceData` for the other. No `opts` passed — the default
 * `quantity: 1` is correct for a single-unit card display (matches `variantScopedPrice.ts`'s own
 * no-opts calls for the same reason). No hardcoded fallback currency — if either the price or the
 * currency is absent, formatting is skipped rather than guessed, matching `productInfo.ts`'s and
 * `recentlyViewedCard.ts`'s own "no hardcoded fallback currency" rule.
 */
const selectPriceFields = (
  product: RecentlyViewedFullHistoryProduct,
  formatPrice: FormatPrice,
): Pick<RecentlyViewedFullHistoryCard, 'currentPrice' | 'originalPrice'> => {
  const priceData: SfccPriceData = getPriceData(product);

  const currentPrice =
    typeof priceData.currentPrice === 'number' && product.currency
      ? formatPrice(priceData.currentPrice, product.currency)
      : undefined;

  // Only set when isOnSale is true -- a not-on-sale product must not render a crossed-out price
  // identical to its current one.
  const originalPrice =
    priceData.isOnSale && typeof priceData.listPrice === 'number' && product.currency
      ? formatPrice(priceData.listPrice, product.currency)
      : undefined;

  return { currentPrice, originalPrice };
};

/**
 * @param product - A plain Commerce API product from `recentlyViewedProductFetch.ts`'s own
 *   `getProducts` call, or `undefined`/`null` while that data is not yet available.
 * @param formatPrice - Currency formatter, normally `intl.formatNumber`.
 * @returns Props for the `plp`-variation `ZimmProductCard`, or `null` when the product has no
 *   usable name or no usable image — never a broken card, never a throw. Same hard-gate contract
 *   as `recentlyViewedCard.ts`'s own `selectRecentlyViewedCard`. `onAddToBag`/`selectedSizeChipValue`/
 *   `onSizeChipSelect` are deliberately not populated here — same split
 *   `productListCardMapper.ts`'s own `ProductListCardResult` documents: this mapper is a pure data
 *   function with no per-card selection state of its own, so the page container wires those three
 *   (see `overrides/app/pages/recentlyViewed/index.tsx`'s own per-card size-chip state).
 */
export const selectRecentlyViewedFullHistoryCard = (
  product: RecentlyViewedFullHistoryProduct | undefined | null,
  formatPrice: FormatPrice,
): RecentlyViewedFullHistoryCard | null => {
  if (!product?.name) return null;

  // One resolution feeds primaryImage, the gallery, the hover-swap image, and the broken-image
  // fallback candidates below — see selectColourScopedImages's own docblock for why.
  const scopedImages = selectColourScopedImages(product, resolveViewedColour(product));
  const [firstImage] = scopedImages;
  if (!firstImage) return null;

  // Required-non-empty alt for the primary position only — shared resolveRequiredAlt
  // (productCardMappingHelpers.ts, also used by recentlyViewedCard.ts's own primary image). Was
  // `firstImage.alt || product.name` here (no `.trim()`) until 2026-09-10, a real gap this shared
  // helper closes: a whitespace-only alt is a non-empty string, so it passed straight through
  // instead of falling back — confirmed with a real whitespace-only-alt repro. The rest of
  // scopedImages keeps toCardImage's plain alt (matching productListCardMapper.ts's own gallery
  // images, which get no such treatment either) since only the primary slot ever carried this
  // extra safeguard.
  const primaryImage: ZimmProductCardImage = { ...firstImage, alt: resolveRequiredAlt(firstImage.alt, product.name) };

  const { currentPrice, originalPrice } = selectPriceFields(product, formatPrice);

  return {
    id: product.id,
    href: productUrlBuilder({ id: product.id }),
    name: product.name,
    headingLevel: 'h3',
    primaryImage,
    // Ordered backup candidates if primaryImage itself fails to load — same real, live defect
    // productListCardMapper.ts's own primaryImageFallbacks closes.
    primaryImageFallbacks: scopedImages,
    // The second image in the same colour-scoped sequence — revealed on hover. undefined when
    // there is no second image, which ZimmProductCardMedia already treats as "no swap".
    hoverImage: scopedImages[1],
    images: scopedImages.length > 1 ? scopedImages : undefined,
    currentPrice,
    originalPrice,
    // product.master is this master product's own overall orderability (ShopperProductsTypes.Master
    // — confirmed via the SDK's own type) — the equivalent of productListCardMapper.ts's flat
    // hit.orderable for this input shape, which has no such flat field of its own.
    isUnavailable: product.master?.orderable === false,
    // Single highest-priority badge -- confirmed live, 2026-09-09 (see this module's own docblock's
    // "Badge" section). SFCC-225's own hook already sorts c_productBadges by badgePriorityOrder
    // before this ever reaches the frontend, matching productListCardMapper.ts's own identical read.
    badge: product.c_productBadges?.[0]?.productBadge,
    variation: 'plp',
    sizeChipValues: selectSizeChipValues(product),
  };
};

